  var conversion=ParseQuickConversion(query);if(conversion!=null){RenderQuickConversion(conversion);SetQuickSearchExpanded(true);return;}
  if(quickMode=="calc"){var hint=QuickCard();hint.Children.Add(Text("Complete the expression to see its result.",12,mutedBrush));SetQuickSearchExpanded(true);return;}string normalized=NormalizeAppText(query).Trim();var apps=catalog.Concat(DockEntries()).Concat(cfg.StartPins).Select(x=>new{Item=x,Score=QuickSearchScore(normalized,x.Name+" "+x.Target)}).Where(x=>x.Score<999).GroupBy(x=>x.Item.Target,StringComparer.OrdinalIgnoreCase).Select(x=>x.OrderBy(y=>y.Score).First()).OrderBy(x=>x.Score).ThenBy(x=>x.Item.Name).Take(6).Select(x=>x.Item).ToList();
  var files=quickFileIndex.Select(x=>new{Item=x,Score=QuickSearchScore(normalized,Path.GetFileName(x)+" "+x)}).Where(x=>x.Score<999).OrderBy(x=>x.Score).ThenBy(x=>x.Item.Length).Take(6).Select(x=>x.Item).ToList();
  var settings=WindowsSettings().Select(x=>new{Item=x,Score=QuickSearchScore(normalized,x.Item1+" "+x.Item2)}).Where(x=>x.Score<999).OrderBy(x=>x.Score).ThenBy(x=>x.Item.Item1).Take(5).Select(x=>x.Item).ToList();
