 static string QuickNumber(double value){if(Math.Abs(value)>0&&Math.Abs(value)<.0001)return value.ToString("0.###E+0",CultureInfo.InvariantCulture);return value.ToString("0.####",CultureInfo.CurrentCulture);}
 static string QuickUnit(string unit){unit=unit.ToLowerInvariant();return unit=="c"?"°C":unit=="f"?"°F":new[]{"usd","ngn","eur","gbp","cad","jpy","aud"}.Contains(unit)?unit.ToUpperInvariant():unit;}
 static DateTime SafeFileTime(string path){try{return File.GetLastWriteTimeUtc(path);}catch{return DateTime.MinValue;}}
 int QuickSearchScore(string query,string candidate){string text=NormalizeAppText(candidate).Trim();if(query.Length==0)return 0;if(text==query)return 0;if(text.StartsWith(query))return 1;if(text.Contains(query))return 2;var words=query.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries);if(words.Length>1&&words.All(text.Contains))return 3;int at=0,gaps=0;foreach(char c in text){if(at>=query.Length)break;if(c==query[at])at++;else if(at>0)gaps++;}return at==query.Length?4+Math.Min(20,gaps/4):999;}
 void EnsureQuickFileIndex(){if(quickFilesLoading||quickFileIndex.Count>0)return;quickFilesLoading=true;Task.Run(()=>BuildQuickFileIndex()).ContinueWith(task=>Dispatcher.BeginInvoke(new Action(()=>{quickFilesLoading=false;if(task.Status==TaskStatus.RanToCompletion)quickFileIndex=task.Result;if(quickSearchWindow!=null&&quickSearchWindow.IsVisible)RenderQuickSearch();})));}
 List<string> BuildQuickFileIndex(){var results=new List<string>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string root in new[]{Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),Environment.GetFolderPath(Environment.SpecialFolder.MyPictures),Environment.GetFolderPath(Environment.SpecialFolder.MyMusic),Environment.GetFolderPath(Environment.SpecialFolder.MyVideos),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Downloads")})IndexQuickFolder(root,results,seen,0);return results;}
 void IndexQuickFolder(string folder,List<string> results,HashSet<string> seen,int depth){if(depth>7||results.Count>=20000||String.IsNullOrEmpty(folder)||!Directory.Exists(folder))return;try{foreach(string file in Directory.EnumerateFiles(folder)){if(results.Count>=20000)break;if(seen.Add(file))results.Add(file);}foreach(string child in Directory.EnumerateDirectories(folder)){if(results.Count>=20000)break;try{var info=new DirectoryInfo(child);if((info.Attributes&FileAttributes.Hidden)==0&&(info.Attributes&FileAttributes.ReparsePoint)==0)IndexQuickFolder(child,results,seen,depth+1);}catch{}}}catch{}}

 bool QuickMathLike(string value){return value.Any(Char.IsDigit)&&value.Any(c=>"+-*/^".Contains(c))&&value.All(c=>Char.IsDigit(c)||Char.IsWhiteSpace(c)||".+-*/^()".Contains(c));}
 bool TryQuickMath(string value,out double result){try{var parser=new QuickMathParser(value);result=parser.Parse();return !Double.IsNaN(result)&&!Double.IsInfinity(result)&&parser.Complete;}catch{result=0;return false;}}
 sealed class QuickMathParser { readonly string text;int at;public bool Complete{get{Skip();return at==text.Length;}}public QuickMathParser(string value){text=value;}void Skip(){while(at<text.Length&&Char.IsWhiteSpace(text[at]))at++;}bool Take(char c){Skip();if(at<text.Length&&text[at]==c){at++;return true;}return false;}public double Parse(){double v=Expression();if(!Complete)throw new FormatException();return v;}double Expression(){double v=Term();while(true){if(Take('+'))v+=Term();else if(Take('-'))v-=Term();else return v;}}double Term(){double v=Power();while(true){if(Take('*'))v*=Power();else if(Take('/'))v/=Power();else return v;}}double Power(){double v=Primary();if(Take('^'))v=Math.Pow(v,Power());return v;}double Primary(){if(Take('-'))return-Primary();if(Take('+'))return Primary();if(Take('(')){double v=Expression();if(!Take(')'))throw new FormatException();return v;}Skip();int start=at;while(at<text.Length&&(Char.IsDigit(text[at])||text[at]=='.'))at++;double n;if(start==at||!Double.TryParse(text.Substring(start,at-start),NumberStyles.Float,CultureInfo.InvariantCulture,out n))throw new FormatException();return n;}}

 Conversion ParseQuickConversion(string query){
  var match=System.Text.RegularExpressions.Regex.Match(query,@"^\s*([+-]?[0-9]*\.?[0-9]+)\s*([a-zA-Z°²/]+)\s+(?:to|in)\s+([a-zA-Z°²/]+)\s*$",System.Text.RegularExpressions.RegexOptions.IgnoreCase);if(!match.Success)return null;double amount;if(!Double.TryParse(match.Groups[1].Value,NumberStyles.Float,CultureInfo.InvariantCulture,out amount))return null;string from=QuickAlias(match.Groups[2].Value),to=QuickAlias(match.Groups[3].Value);
  if(currencyRates.ContainsKey(from)&&currencyRates.ContainsKey(to))return new Conversion{Amount=amount,From=from,To=to,Value=amount/currencyRates[from]*currencyRates[to],Kind="currency",Alternatives=new[]{"usd","ngn","eur","gbp","cad","jpy","aud"},LiveRate=(DateTime.UtcNow-currencyRateTime).TotalHours<12};
  if((from=="c"||from=="f")&&(to=="c"||to=="f")){double converted=from==to?amount:from=="c"?amount*9/5+32:(amount-32)*5/9;return new Conversion{Amount=amount,From=from,To=to,Value=converted,Kind="temperature",Alternatives=new[]{"c","f"}};}
  foreach(var group in QuickUnitGroups()){if(group.ContainsKey(from)&&group.ContainsKey(to))return new Conversion{Amount=amount,From=from,To=to,Value=amount*group[from]/group[to],Kind="unit",Alternatives=group.Keys.ToArray()};}return null;
 }
 static string QuickAlias(string value){value=value.Trim().ToLowerInvariant().Replace("°","");var aliases=new Dictionary<string,string>{{"lbs","lb"},{"pounds","lb"},{"pound","lb"},{"kilograms","kg"},{"kilogram","kg"},{"meters","m"},{"meter","m"},{"metres","m"},{"miles","mi"},{"mile","mi"},{"feet","ft"},{"inches","in"},{"fahrenheit","f"},{"celsius","c"},{"liters","l"},{"litres","l"},{"gallons","gal"},{"mph","mi/h"},{"kph","km/h"}};string alias;return aliases.TryGetValue(value,out alias)?alias:value;}
 static IEnumerable<Dictionary<string,double>> QuickUnitGroups(){yield return new Dictionary<string,double>(StringComparer.OrdinalIgnoreCase){{"mm",.001},{"cm",.01},{"m",1},{"km",1000},{"in",.0254},{"ft",.3048},{"yd",.9144},{"mi",1609.344}};yield return new Dictionary<string,double>(StringComparer.OrdinalIgnoreCase){{"mg",.000001},{"g",.001},{"kg",1},{"oz",.0283495},{"lb",.453592}};yield return new Dictionary<string,double>(StringComparer.OrdinalIgnoreCase){{"ml",.001},{"l",1},{"gal",3.785411784},{"qt",.946352946},{"cup",.236588236}};yield return new Dictionary<string,double>(StringComparer.OrdinalIgnoreCase){{"m/s",1},{"km/h",.277777778},{"mi/h",.44704},{"knot",.514444}};}
 async void UpdateCurrencyRates(string query){if(currencyLoading||(DateTime.UtcNow-currencyRateTime).TotalHours<12)return;currencyLoading=true;try{using(var client=new HttpClient()){client.Timeout=TimeSpan.FromSeconds(5);string json=await client.GetStringAsync("https://open.er-api.com/v6/latest/USD");var data=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<Dictionary<string,object>>(json);var rates=(Dictionary<string,object>)data["rates"];foreach(string code in new[]{"USD","NGN","EUR","GBP","CAD","JPY","AUD"})if(rates.ContainsKey(code))currencyRates[code.ToLowerInvariant()]=Convert.ToDouble(rates[code],CultureInfo.InvariantCulture);currencyRateTime=DateTime.UtcNow;if(quickSearchWindow!=null&&(quickMode=="currency"||quickQuery==query))RenderQuickSearch();}}catch(Exception error){Log("Currency rates: "+error.Message);}finally{currencyLoading=false;}}
 public string QuickSearchSelfTest(){double math;if(!TryQuickMath("(18+4)/2",out math)||Math.Abs(math-11)>.001)return "FAILED: quick search math";var weight=ParseQuickConversion("5kg to lbs");if(weight==null||Math.Abs(weight.Value-11.0231)>.01)return "FAILED: quick search unit conversion";var temperature=ParseQuickConversion("98f to c");if(temperature==null||Math.Abs(temperature.Value-36.6667)>.01)return "FAILED: quick search temperature conversion";var currency=ParseQuickConversion("20 usd to ngn");if(currency==null||currency.Value<=0)return "FAILED: quick search currency conversion";if(QuickSearchScore("vscd","Visual Studio Code")>=999||QuickSearchScore("bt dev","Bluetooth devices")>=999)return "FAILED: fuzzy search";return "Quick search math, conversions, and fuzzy matching passed";}
